/bin/zsh -lc 'set -e
base=http://localhost:3101
mkdir -p .qf/originals .qf/runs loops
curl -fsS "$base/registry/catalog.json" -o /tmp/qfactory-catalog.json
node - <<'"'NODE'
const fs=require('fs'), crypto=require('crypto'), cp=require('child_process');
const c=JSON.parse(fs.readFileSync('/tmp/qfactory-catalog.json','utf8'));
const e=c.loops.find(x=>x.id==='webhook-relay');
if("'!e) throw new Error('"'webhook-relay not found');
const url='http://localhost:3101/registry/'+e.file.replace(/"'^.*?'"\\//,'');
const bytes=cp.execFileSync('curl',['-fsS',url]);
const got=crypto.createHash('sha256').update(bytes).digest('hex');
if(got"'!==e.sha256) throw new Error(`manifest checksum mismatch: ${got} != ${e.sha256}`);
fs.writeFileSync('"'.qf/originals/webhook-relay-1.0.0.yaml',bytes);
fs.writeFileSync('.qf/originals/webhook-relay-1.0.0.metadata.json',JSON.stringify({sourceUrl:url,sourceFile:e.file,id:e.id,version:e.version,sha256:e.sha256,catalogVersion:c.catalogVersion,releaseVersion:c.releaseVersion,engine:e.engine,origin:e.origin},null,2)+'\\n');
console.log(JSON.stringify({sourceUrl:url,id:e.id,version:e.version,sha256:got},null,2));
NODE
printf '%s\\n' '--- original manifest ---'
sed -n '1,240p' .qf/originals/webhook-relay-1.0.0.yaml
printf '%s\\n' '--- provenance ---'
sed -n '1,200p' .qf/originals/webhook-relay-1.0.0.metadata.json"

