/bin/zsh -lc 'set -e
run=$(find loops/.qf/runs -type f -name '"'*.json' -print | head -1)
printf '%s\\n' '--- retained output ---'
sed -n '1,300p' \""'$run"
printf '"'%s\\n' '--- independent verifier ---'
node - \""'$run" <<'"'NODE'
const fs=require('fs');
const run=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
if(run.status"'!=='"'success') throw new Error("'`run status ${run.status}`);
const rows=run.steps || run.stepResults || [];
const row=Array.isArray(rows) ? rows.find(x=>x.stepId==='"'wr-fetch'||x.id==='wr-fetch') : rows['wr-fetch'];
const out=row?.output;
const json=out?.json;
if(JSON.stringify(json)"'!==JSON.stringify({project:'"'synthetic-qf',items:[1,2,3],total:6})) throw new Error('unexpected retained JSON: '+JSON.stringify(json));
console.log(JSON.stringify({status:run.status,step:'wr-fetch',checked:json,independentCheck:'PASS'},null,2));
NODE
printf '%s\\n' '--- adaptation safety checks ---'
